CREATE EXTENSION IF NOT EXISTS "pgcrypto";
CREATE TABLE IF NOT EXISTS "projects" ("id" uuid PRIMARY KEY DEFAULT gen_random_uuid(),"name" text NOT NULL,"status" text NOT NULL DEFAULT 'draft',"created_at" timestamptz NOT NULL DEFAULT now(),"updated_at" timestamptz NOT NULL DEFAULT now());
CREATE INDEX IF NOT EXISTS "projects_updated_at_idx" ON "projects" ("updated_at");
CREATE TABLE IF NOT EXISTS "assets" ("id" uuid PRIMARY KEY DEFAULT gen_random_uuid(),"project_id" uuid NOT NULL REFERENCES "projects"("id") ON DELETE CASCADE,"kind" text NOT NULL DEFAULT 'primary',"original_filename" text NOT NULL,"mime_type" text NOT NULL,"original_storage_key" text NOT NULL,"proxy_storage_key" text,"mezzanine_storage_key" text,"waveform_storage_key" text,"duration_ms" integer,"width" integer,"height" integer,"fps" real,"audio_channels" integer,"status" text NOT NULL DEFAULT 'uploaded',"error_message" text,"analysis_json" jsonb,"created_at" timestamptz NOT NULL DEFAULT now(),"updated_at" timestamptz NOT NULL DEFAULT now());
CREATE INDEX IF NOT EXISTS "assets_project_id_idx" ON "assets" ("project_id"); CREATE INDEX IF NOT EXISTS "assets_status_idx" ON "assets" ("status");
CREATE TABLE IF NOT EXISTS "transcripts" ("id" uuid PRIMARY KEY DEFAULT gen_random_uuid(),"asset_id" uuid NOT NULL REFERENCES "assets"("id") ON DELETE CASCADE,"language" text NOT NULL,"full_text" text NOT NULL,"provider" text NOT NULL,"created_at" timestamptz NOT NULL DEFAULT now(),"updated_at" timestamptz NOT NULL DEFAULT now()); CREATE UNIQUE INDEX IF NOT EXISTS "transcripts_asset_id_unique" ON "transcripts" ("asset_id");
CREATE TABLE IF NOT EXISTS "transcript_words" ("id" uuid PRIMARY KEY DEFAULT gen_random_uuid(),"transcript_id" uuid NOT NULL REFERENCES "transcripts"("id") ON DELETE CASCADE,"word_index" integer NOT NULL,"text" text NOT NULL,"normalized_text" text NOT NULL,"start_ms" integer NOT NULL,"end_ms" integer NOT NULL,"confidence" numeric(5,4)); CREATE UNIQUE INDEX IF NOT EXISTS "transcript_words_transcript_index_unique" ON "transcript_words" ("transcript_id","word_index"); CREATE INDEX IF NOT EXISTS "transcript_words_time_idx" ON "transcript_words" ("transcript_id","start_ms");
CREATE TABLE IF NOT EXISTS "timelines" ("id" uuid PRIMARY KEY DEFAULT gen_random_uuid(),"project_id" uuid NOT NULL REFERENCES "projects"("id") ON DELETE CASCADE,"current_version" integer NOT NULL DEFAULT 0,"state_json" jsonb NOT NULL,"created_at" timestamptz NOT NULL DEFAULT now(),"updated_at" timestamptz NOT NULL DEFAULT now()); CREATE UNIQUE INDEX IF NOT EXISTS "timelines_project_id_unique" ON "timelines" ("project_id");
CREATE TABLE IF NOT EXISTS "edit_commands" ("id" uuid PRIMARY KEY DEFAULT gen_random_uuid(),"project_id" uuid NOT NULL REFERENCES "projects"("id") ON DELETE CASCADE,"user_text" text NOT NULL,"planner_mode" text NOT NULL,"plan_json" jsonb NOT NULL,"status" text NOT NULL DEFAULT 'planning',"error_message" text,"created_at" timestamptz NOT NULL DEFAULT now(),"completed_at" timestamptz); CREATE INDEX IF NOT EXISTS "edit_commands_project_created_idx" ON "edit_commands" ("project_id","created_at");
CREATE TABLE IF NOT EXISTS "timeline_snapshots" ("id" uuid PRIMARY KEY DEFAULT gen_random_uuid(),"timeline_id" uuid NOT NULL REFERENCES "timelines"("id") ON DELETE CASCADE,"version" integer NOT NULL,"name" text,"state_json" jsonb NOT NULL,"command_id" uuid REFERENCES "edit_commands"("id") ON DELETE SET NULL,"created_at" timestamptz NOT NULL DEFAULT now()); CREATE UNIQUE INDEX IF NOT EXISTS "timeline_snapshots_timeline_version_unique" ON "timeline_snapshots" ("timeline_id","version");
CREATE TABLE IF NOT EXISTS "processing_jobs" ("id" uuid PRIMARY KEY DEFAULT gen_random_uuid(),"project_id" uuid NOT NULL REFERENCES "projects"("id") ON DELETE CASCADE,"asset_id" uuid REFERENCES "assets"("id") ON DELETE CASCADE,"type" text NOT NULL,"bull_job_id" text,"status" text NOT NULL DEFAULT 'queued',"progress" integer NOT NULL DEFAULT 0,"error_message" text,"created_at" timestamptz NOT NULL DEFAULT now(),"updated_at" timestamptz NOT NULL DEFAULT now()); CREATE INDEX IF NOT EXISTS "processing_jobs_project_status_idx" ON "processing_jobs" ("project_id","status");
CREATE TABLE IF NOT EXISTS "exports" ("id" uuid PRIMARY KEY DEFAULT gen_random_uuid(),"project_id" uuid NOT NULL REFERENCES "projects"("id") ON DELETE CASCADE,"timeline_version" integer NOT NULL,"status" text NOT NULL DEFAULT 'queued',"progress" integer NOT NULL DEFAULT 0,"output_storage_key" text,"width" integer NOT NULL,"height" integer NOT NULL,"duration_ms" integer,"error_message" text,"created_at" timestamptz NOT NULL DEFAULT now(),"completed_at" timestamptz); CREATE INDEX IF NOT EXISTS "exports_project_created_idx" ON "exports" ("project_id","created_at");
